mapper.select:
select cm.sender_id as senderId, max(cm.create_time) as lastMessageTime from xg_chat_message cm where cm.del_flag = 0 and cm.chat_type = 2 and cm.receiver_id = #{groupId} and cm.sender_id in
#{senderId}
group by cm.sender_id

select cm.id, cm.sender_id as senderId, cm.receiver_id as receiverId, cm.message, cm.chat_type as chatType, cm.message_type as messageType, cm.withdrawn, cm.edited, cm.edit_time, cm.reply_to_id as replyToId, cm.reply_content as replyContent, cm.at_users as atUsers, date_format(cm.create_time, '%Y-%m-%d %H:%i:%s') as createTime from xg_chat_message cm where cm.del_flag = 0
and cm.id > #{lastId}
order by cm.id asc limit #{pageSize}

select m.id as messageId, case when m.sender_id = #{userId} then m.receiver_id else m.sender_id end as peerId, u.username as peerName, u.avatar as peerAvatar, case when m.sender_id = #{userId} then 'outgoing' else 'incoming' end as direction, m.message as message, date_format(m.create_time, '%Y-%m-%d %H:%i:%s') as createTime from xg_chat_message m left join xg_user u on u.id = case when m.sender_id = #{userId} then m.receiver_id else m.sender_id end and u.del_flag = 0 where m.del_flag = 0 and m.chat_type = 1 and (m.sender_id = #{userId} or m.receiver_id = #{userId}) and (m.withdrawn is null or m.withdrawn = 0) and (m.message_type = 9 or (m.message_type = 6 and m.message like '%"kind":"video"%'))
and m.sender_id <> #{userId} and json_unquote(json_extract(m.message, '$.outcome')) in ('rejected', 'timeout', 'busy')
and u.username like concat('%', #{keyword}, '%')
and m.create_time >= #{startTime}
and m.create_time <= #{endTime}
and not exists ( select 1 from xg_call_record_deleted d where d.user_id = #{userId} and d.message_id = m.id ) order by m.create_time desc, m.id desc

select cm.id, cm.sender_id as senderId, cm.receiver_id as receiverId, cm.message,
       cm.chat_type as chatType, cm.message_type as messageType,
       date_format(cm.create_time, '%Y-%m-%d %H:%i:%s') as createTime
from xg_chat_message cm
where cm.del_flag = 0
  and cm.create_time >= #{afterTime}

    and cm.id > #{lastId}

order by cm.id asc
    limit #{pageSize}
